102	    /**
103	     * The request header carrying a client-supplied idempotency key for the create endpoint. When a create
104	     * repeats with a key already seen, the originally created owner is returned instead of a duplicate.
105	     */
106	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
