309	    /**
310	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
311	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
312	     *
313	     * @param fields the submitted owner fields
314	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
315	     *                                        {@code null} or blank, or if the owner supplies no address
316	     *                                        in either form (a blank structured {@code addressLine1} and a
317	     *                                        blank flat {@code address}, each measured after normalization)
318	     */
319	    /**
320	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
321	     *
322	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
323	     */
324	    private String idempotencyKey() {
325	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
326	        if (key == null || key.isBlank()) {
327	            return null;
328	        }
329	        return key.strip();
330	    }
331	
332	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
333	        List<String> missing = new ArrayList<>();
334	        if (isBlank(fields.getFirstName())) {
335	            missing.add("firstName");
336	        }
337	        if (isBlank(fields.getLastName())) {
338	            missing.add("lastName");
339	        }
340	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
341	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
342	        if (!hasStructuredAddress && !hasFlatAddress) {
343	            missing.add("address");
344	        }
345	        if (isBlank(fields.getCity())) {
346	            missing.add("city");
347	        }
348	        if (isBlank(fields.getTelephone())) {
349	            missing.add("telephone");
350	        }
351	        if (!missing.isEmpty()) {
352	            throw new RequiredFieldsMissingException(missing);
353	        }
354	    }
355	
356	    private boolean isBlank(String value) {
357	        return value == null || value.isBlank();
358	    }
359	
360	    /**
361	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
362	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
363	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
364	     */
365	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
366	        "NSW", new int[] {2000, 2099},
367	        "VIC", new int[] {3000, 3099},
368	        "QLD", new int[] {4000, 4099});
369	
370	    /**
371	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
372	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
373	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
374	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
375	     *
376	     * @param postcode the submitted postcode, or {@code null} when omitted
377	     * @param city the owner's city, used to derive the region whose range constrains the postcode
378	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
379	     *                                  city's region
380	     */
381	    private void validatePostcode(String postcode, String city) {
382	        if (postcode == null) {
383	            return;
384	        }
385	        if (!postcode.matches("[0-9]{4}")) {
386	            throw new InvalidPostcodeException(postcode);
387	        }
388	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
389	        if (range == null) {
390	            return;
391	        }
392	        int value = Integer.parseInt(postcode);
393	        if (value < range[0] || value > range[1]) {
394	            throw new InvalidPostcodeException(postcode);
395	        }
396	    }
397	
398	    /**
399	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
400	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
401	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
402	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
403	     * <p>
404	     * Where a per-country rule is defined the national-number length is validated against the country
405	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
406	     * requires exactly 10.
407	     *
408	     * @param telephone the raw telephone value from the request
409	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
410	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
411	     */
412	    private String normalizeTelephone(String telephone) {
413	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
414	        String digits;
415	        if (cleaned.startsWith("+")) {
416	            digits = cleaned.substring(1);
417	        } else {
418	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
419	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
420	            digits = "61" + national;
421	        }
422	        if (!digits.matches("[0-9]{8,15}")) {
423	            throw new InvalidTelephoneException(cleaned);
424	        }
425	        // Validate the national-number length against the country code where a rule is defined.
426	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
427	            throw new InvalidTelephoneException(cleaned);
428	        }
429	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
430	            throw new InvalidTelephoneException(cleaned);
431	        }
432	        return "+" + digits;
433	    }
434	
435	    /**
436	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
437	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
438	     * lower-cased.
439	     *
440	     * @param email the raw email value from the request, or {@code null} if omitted
441	     * @return the lower-cased email, or {@code null} if none was supplied
442	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
443	     */
444	    private String normalizeEmail(String email) {
445	        if (email == null) {
446	            return null;
447	        }
448	        String trimmed = email.strip();
449	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
450	            throw new InvalidEmailException(email);
451	        }
452	        String normalized = trimmed.toLowerCase(Locale.ROOT);
453	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
454	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
455	            throw new DisposableEmailDomainException(domain);
456	        }
457	        return normalized;
458	    }
459	
460	    /**
461	     * Applies the owner's address in whichever form the request supplied, preferring the structured
462	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
463	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
464	     * value: the normalized {@code addressLine1}, with a single space and the normalized
465	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
466	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
467	     * flat-address contract backward-compatible.
468	     *
469	     * @param owner the owner being created, mapped straight from the request
470	     */
471	    private void applyAddress(Owner owner) {
472	        if (!isBlank(owner.getAddressLine1())) {
473	            String line1 = normalizeAddress(owner.getAddressLine1());
474	            owner.setAddressLine1(line1);
475	            String composed = line1;
476	            if (!isBlank(owner.getAddressLine2())) {
477	                String line2 = normalizeAddress(owner.getAddressLine2());
478	                owner.setAddressLine2(line2);
479	                composed = line1 + " " + line2;
480	            } else {
481	                owner.setAddressLine2(null);
482	            }
483	            owner.setAddress(composed);
484	        } else {
485	            owner.setAddressLine1(null);
486	            owner.setAddressLine2(null);
487	            owner.setAddress(normalizeAddress(owner.getAddress()));
488	        }
489	    }
490	
491	    /**
492	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
493	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
494	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
495	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
496	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
497	     *
498	     * @param address the raw address value from the request (may be {@code null})
499	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
500	     */
501	    private String normalizeAddress(String address) {
502	        if (address == null) {
503	            return "";
504	        }
505	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
506	        if (collapsed.isEmpty()) {
507	            return "";
508	        }
509	        String[] tokens = collapsed.split(" ");
510	        StringBuilder sb = new StringBuilder(collapsed.length());
511	        for (int i = 0; i < tokens.length; i++) {
512	            if (i > 0) {
513	                sb.append(' ');
514	            }
515	            sb.append(expandAddressAbbreviation(tokens[i]));
516	        }
517	        return sb.toString();
518	    }
519	
520	    /**
521	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
522	     * returns the token unchanged when it is not a recognised abbreviation.
523	     *
524	     * @param token an upper-cased whole-word address token
525	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
526	     */
527	    private String expandAddressAbbreviation(String token) {
528	        return switch (token) {
529	            case "ST" -> "STREET";
530	            case "RD" -> "ROAD";
531	            case "AVE" -> "AVENUE";
532	            default -> token;
533	        };
534	    }
535	
536	    /**
537	     * Builds the customer code assigned to a newly created owner, formatted {@code '<REGION>-<HASH8>'}
538	     * where {@code REGION} is the region derived from the owner's postcode (falling back to the city when
539	     * the postcode resolves to no known region), the same derivation that yields the owner's locality, and
540	     * {@code HASH8} is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
541	     * normalized telephone concatenated with the owner's last name (e.g. {@code 'NSW-1A2B3C4D'}).
542	     * <p>
543	     * Should the computed code collide with an existing owner's {@code customerCode}, it is de-duplicated
544	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
545	     * held by any existing owner; the de-duplicated code is returned.
546	     *
547	     * @param owner the owner being created, with normalized telephone and postcode already set
548	     * @return the assigned, collision-free customer code
549	     */
550	    private String generateCustomerCode(Owner owner) {
551	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
552	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
553	            .substring(0, 8).toUpperCase(Locale.ROOT);
554	        String base = region + "-" + hash8;
555	        Set<String> existing = this.clinicService.findAllOwners().stream()
556	            .map(Owner::getCustomerCode)
557	            .filter(code -> code != null)
558	            .collect(java.util.stream.Collectors.toSet());
559	        if (!existing.contains(base)) {
560	            return base;
561	        }
562	        int n = 2;
563	        while (existing.contains(base + "-" + n)) {
564	            n++;
565	        }
566	        return base + "-" + n;
567	    }
568	
569	    /**
570	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
571	     *
572	     * @param value the value to hash
573	     * @return the 64-character lower-case hex SHA-256 digest
574	     */
575	    private String sha256Hex(String value) {
576	        try {
577	            byte[] digest = MessageDigest.getInstance("SHA-256")
578	                .digest(value.getBytes(StandardCharsets.UTF_8));
579	            StringBuilder sb = new StringBuilder(digest.length * 2);
580	            for (byte b : digest) {
581	                sb.append(String.format("%02x", b));
582	            }
583	            return sb.toString();
584	        } catch (NoSuchAlgorithmException e) {
585	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
586	        }
587	    }
588	
589	    /**
590	     * Counts how many existing owners already share the given first name and last name, compared
591	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
592	     * owner being created.
593	     *
594	     * @param firstName the first name of the owner being created
595	     * @param lastName the last name of the owner being created
596	     * @return the number of existing owners with the same first and last name (case-insensitively)
597	     */
598	    private int countNamesakes(String firstName, String lastName) {
599	        return (int) this.clinicService.findAllOwners().stream()
600	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
601	                && lastName.equalsIgnoreCase(existing.getLastName()))
602	            .count();
603	    }
604	
605	    /**
606	     * Computes the size of the owner's household: the number of existing owners already sharing the given
607	     * {@code householdId} plus the owner being created itself. The existing count is taken before the new
608	     * owner is persisted, so adding one for the owner yields the household's total membership including it
609	     * (e.g. two existing members give a household size of 3 for the third member). Households are keyed on
610	     * the deterministic {@code householdId} (derived from last name and postcode).
611	     *
612	     * @param householdId the computed household identifier of the owner being created
613	     * @return the household size including the owner being created (at least 1)
614	     */
615	    private int countHouseholdSize(String householdId) {
616	        long existing = this.clinicService.findAllOwners().stream()
617	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
618	            .count();
619	        return (int) existing + 1;
620	    }
621	
622	    /**
623	     * Computes the membership level assigned to a newly created owner, applying the household level ceiling.
624	     * The owner's own (uncapped) level cannot exceed one above the current maximum membership level among
625	     * their existing household members, where every level is measured against the household's current size
626	     * (the owner's just-computed {@code householdSize}). When the owner has no existing household member the
627	     * ceiling does not apply and the uncapped level is returned. The count is taken before the new owner is
628	     * persisted, so it excludes the owner being created; the existing members share the deterministic
629	     * {@code householdId} and any soft-deleted owner is ignored.
630	     *
631	     * @param owner the owner being created, with its {@code householdId} and {@code householdSize} already set
632	     * @return the owner's membership level, capped at one above the existing household maximum
633	     */
634	    private Integer computeMembershipLevel(Owner owner) {
635	        Integer householdSize = owner.getHouseholdSize();
636	        Integer ownLevel = this.ownerMapper.membershipLevelForHouseholdSize(owner, householdSize);
637	        String householdId = owner.getHouseholdId();
638	        int maxExisting = this.clinicService.findAllOwners().stream()
639	            .filter(existing -> !isDeleted(existing))
640	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
641	            .mapToInt(existing -> this.ownerMapper.membershipLevelForHouseholdSize(existing, householdSize))
642	            .max()
643	            .orElse(-1);
644	        if (maxExisting < 0) {
645	            return ownLevel;
646	        }
647	        return Math.min(ownLevel, maxExisting + 1);
648	    }
649	
650	    /**
651	     * The maximum number of owners permitted in a single city. A create request whose city already
652	     * holds this many owners is rejected.
653	     */
654	    private static final int CITY_OWNER_LIMIT = 50;
655	
656	    /**
657	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
658	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
659	     * differing only in the casing of their city share one capacity pool. The count is taken before the
660	     * new owner is persisted, so it excludes the owner being created.
661	     *
662	     * @param city the city of the owner being created
663	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
664	     */
665	    private void rejectCityAtCapacity(String city) {
666	        long existing = this.clinicService.findAllOwners().stream()
667	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
668	            .count();
669	        if (existing >= CITY_OWNER_LIMIT) {
670	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
671	        }
672	    }
673	
674	    /**
675	     * The maximum number of owners permitted to be created in a single day. A create request whose
676	     * registration date already holds this many owners is rejected.
677	     */
678	    private static final int DAILY_OWNER_LIMIT = 100;
679	
680	    /**
681	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
682	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
683	     * persisted, so it excludes the owner being created.
684	     *
685	     * @param registrationDate the registration date of the owner being created
686	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
687	     */
688	    /**
689	     * The fixed list of public holidays that are not treated as business days. A registration date that
690	     * lands on one of these dates is rolled forward, just as a weekend is.
691	     */
692	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
693	        LocalDate.of(2026, 1, 1),
694	        LocalDate.of(2026, 1, 26),
695	        LocalDate.of(2026, 4, 25),
696	        LocalDate.of(2026, 12, 25),
697	        LocalDate.of(2026, 12, 28));
698	
699	    /**
700	     * Adjusts an effective registration date so that it always falls on a business day. When the given
701	     * date is a Saturday, a Sunday or a listed public holiday it is rolled forward one day at a time until
702	     * it reaches the next non-holiday business day; a weekday that is not a holiday is returned unchanged.
703	     * This applies equally to a date supplied in the request and to a date defaulted to the server date, and
704	     * the adjusted value is what becomes the owner's {@code registrationDate}, so every value derived from it
705	     * (the membership number's year segment, the daily create-limit count) uses the business-day-adjusted
706	     * date.
707	     *
708	     * @param date the effective registration date, supplied or defaulted
709	     * @return the same date when it is a business day, otherwise the next non-holiday business day
710	     */
711	    private LocalDate rollToBusinessDay(LocalDate date) {
712	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
713	            date = date.plusDays(1);
714	        }
715	        return date;
716	    }
717	
718	    private boolean isWeekend(LocalDate date) {
719	        DayOfWeek day = date.getDayOfWeek();
720	        return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
721	    }
722	
723	    /**
724	     * The number of owners that must already exist for a given day before a further create is flagged as a
725	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
726	     * the created owner carries {@code bulkSignupWarning = true}.
727	     */
728	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
729	
730	    /**
731	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
732	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
733	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
734	     * the daily create-limit rule's accumulation path.
735	     *
736	     * @param registrationDate the registration date of the owner being created
737	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
738	     */
739	    private boolean isBulkSignupDay(LocalDate registrationDate) {
740	        long existing = this.clinicService.findAllOwners().stream()
741	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
742	            .count();
743	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
744	    }
745	
746	    /**
747	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
748	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
749	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
750	     * made against the supplied value before any business-day adjustment.
751	     *
752	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
753	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
754	     */
755	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
756	        if (registrationDate == null) {
757	            return;
758	        }
759	        LocalDate today = LocalDate.now();
760	        if (registrationDate.isAfter(today)) {
761	            throw new FutureRegistrationDateException(registrationDate, today);
762	        }
763	    }
764	
765	    private void rejectDailyLimitReached(LocalDate registrationDate) {
766	        long existing = this.clinicService.findAllOwners().stream()
767	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
768	            .count();
769	        if (existing >= DAILY_OWNER_LIMIT) {
770	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
771	        }
772	    }
773	
774	    /**
775	     * Rejects a create request whose owner collides with an existing owner on the single derived
776	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
777	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
778	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
779	     * household (same {@code householdId}) with different telephones have different keys and are both
780	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
781	     * been computed (deterministically from the last name and postcode) before this check runs, so the
782	     * key compared here is the same one that is later returned.
783	     *
784	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
785	     * @throws DuplicateIdentityException if an existing owner has the same identity key
786	     */
787	    private void rejectDuplicateIdentity(Owner owner) {
788	        String key = identityKey(owner);
789	        boolean taken = this.clinicService.findAllOwners().stream()
790	            .filter(existing -> !isDeleted(existing))
791	            .anyMatch(existing -> key.equals(identityKey(existing)));
792	        if (taken) {
793	            throw new DuplicateIdentityException(key);
794	        }
795	    }
796	
797	    /**
798	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
799	     * while not a hard {@code identityKey} duplicate (that stronger check has already run), shares this
800	     * owner's last name (compared case-insensitively) and exact postcode but carries a different normalized
801	     * telephone. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
802	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
803	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
804	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
805	     * <p>
806	     * A declared household member ({@code sharesHousehold}) is never flagged: sharing a last name and
807	     * postcode is now exactly the household key, so such an owner is a known household member rather than
808	     * a suspected duplicate.
809	     *
810	     * @param owner the owner being created, with normalized telephone and validated postcode already set
811	     * @param sharesHousehold whether the create declared the owner a household member
812	     */
813	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
814	        Integer matchId = null;
815	        if (!sharesHousehold && owner.getPostcode() != null) {
816	            matchId = this.clinicService.findAllOwners().stream()
817	                .filter(existing -> !isDeleted(existing))
818	                .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
819	                    && owner.getPostcode().equals(existing.getPostcode())
820	                    && !telephonesEqual(owner.getTelephone(), existing.getTelephone()))
821	                .map(Owner::getId)
822	                .filter(id -> id != null)
823	                .min(Comparator.naturalOrder())
824	                .orElse(null);
825	        }
826	        owner.setPossibleDuplicate(matchId != null);
827	        owner.setPossibleDuplicateOf(matchId);
828	    }
829	
830	    private boolean telephonesEqual(String a, String b) {
831	        return a == null ? b == null : a.equals(b);
832	    }
833	
834	    /**
835	     * Whether an existing owner has been soft-deleted. A soft-deleted owner is retained and still
836	     * readable, but is ignored by the create endpoint's duplicate and identity checks.
837	     *
838	     * @param owner an existing owner
839	     * @return {@code true} when the owner is flagged deleted, otherwise {@code false}
840	     */
841	    private boolean isDeleted(Owner owner) {
842	        return Boolean.TRUE.equals(owner.getDeleted());
843	    }
844	
845	    /**
846	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
847	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
848	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
849	     * Telephone and email are stored already normalized, so the stored values are used directly.
850	     *
851	     * @param owner the owner whose identity key is being derived
852	     * @return the owner's identity key
853	     */
854	    private String identityKey(Owner owner) {
855	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
856	        String email = owner.getEmail() == null ? "" : owner.getEmail();
857	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
858	        return telephone + "|" + email + "|" + householdId;
859	    }
860	
861	    /**
862	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
863	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
864	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
865	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
866	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
867	     * whether or not {@code sharesHousehold} was requested.
868	     *
869	     * @param owner the owner being created, with its validated postcode already set
870	     * @return the deterministic household identifier
871	     */
872	    private String computeHouseholdId(Owner owner) {
873	        String normalizedLastName = normalizeForComparison(owner.getLastName());
874	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
875	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
876	    }
877	
878	    /**
879	     * Rejects a create request whose owner would join an existing household without declaring it. The
880	     * household is keyed on the computed {@code householdId} (derived from last name and postcode), so any
881	     * existing owner sharing that identifier is already a member of the same household; a further owner is a
882	     * household duplicate. The check is bypassed when the request opted in via {@code sharesHousehold}, in
883	     * which case the owner is created as a declared household member. The (stronger) exact identity-key
884	     * check has already run, so a full duplicate is rejected regardless of {@code sharesHousehold}.
885	     *
886	     * @param owner the owner being created, with its computed {@code householdId} already assigned
887	     * @throws HouseholdDuplicateException if an existing owner already shares the household
888	     */
889	    private void rejectHouseholdDuplicate(Owner owner) {
890	        String householdId = owner.getHouseholdId();
891	        boolean shared = this.clinicService.findAllOwners().stream()
892	            .filter(existing -> !isDeleted(existing))
893	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
894	        if (shared) {
895	            throw new HouseholdDuplicateException(householdId);
896	        }
897	    }
898	
899	    /**
900	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
901	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
902	     * lower-cased.
903	     *
904	     * @param value the raw value to normalize (may be {@code null})
905	     * @return the normalized value, or an empty string when {@code value} is {@code null}
906	     */
907	    private String normalizeForComparison(String value) {
908	        if (value == null) {
909	            return "";
910	        }
911	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
912	    }
913	}
